#!/usr/bin/env python3
# tools/generate-readme-table.py — README category table from categories.yaml.
#
# KA-20.1 (kailash-os#116, spec §1.1) — the no-hand-sync rule: the README's
# category table is GENERATED from the taxonomy, never hand-maintained.
#
# Source resolution (no hand-copies, ever):
#   * default: the LIVE taxonomy — categories.yaml is fetched from the
#     kailash-packages repo's default-branch main HEAD. The README's
#     numbers follow the manifest as the census lanes fill it (the table
#     is regenerated by CI's --check gate and on manifest merges; the
#     gate makes drift visible the day it appears).
#   * --pin: snapshot mode — the kailash-packages node rev is read from
#     the committed flake.lock (the same pin tools/manifest-matrix.py
#     resolves) and that rev's tarball is fetched from GitHub codeload
#     (no floating heads). Renders the taxonomy the OS lock currently
#     builds against — the honest snapshot while no release tag exists
#     (the pin rides tagged releases per the cadence policy).
#   * --manifest <path>: read categories.yaml from a local packages-repo
#     checkout (development against a stacked branch).
#
# Output modes:
#   --emit          print the generated table (markdown) to stdout
#   --check [FILE]  compare FILE (default README.md) against the generated
#                   table and fail with a unified diff on drift (the CI gate)
#
# The generator is deterministic: fixed order (manifest order), fixed
# column set, plain-ASCII padding. PyYAML is used when importable; a
# stdlib-fallback parser covers the manifest's plain-scalar shape
# otherwise (the census rows carry no nested structures to mis-parse).
"""tools/generate-readme-table.py — README category table from categories.yaml (KA-20.1, kailash-os#116).

The README's category table is GENERATED from the taxonomy, never hand-maintained (the no-hand-sync rule).

Source resolution:
  * default: the LIVE taxonomy — categories.yaml from kailash-packages main HEAD.
  * --pin: snapshot mode — the flake.lock kailash-packages node rev (codeload, pinned).
  * --manifest <path>: categories.yaml from a local packages checkout.
  * inline fixture mode (--check-fixture FILE) for the RED/GREEN probe suite.

Modes: --emit prints the table; --check [FILE] compares FILE (default README.md)
against the generated table and fails with a unified diff on drift (the CI gate).

Deterministic output: fixed order (manifest order), fixed columns, plain-ASCII padding.
"""
from __future__ import annotations

import io
import json
import os
import sys
import tarfile
from collections import namedtuple
from urllib.request import Request, urlopen

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

REPO = "kailash-os/kailash-packages"
LOCK_INPUT = "kailash-packages"
LIVE_RAW_URL = (
    "https://raw.githubusercontent.com/kailash-os/kailash-packages"
    "/main/manifest/categories.yaml"
)

# A resolved source document + how to describe it in the table footnote.
#   manifest_path — --manifest <path>: local checkout
#   pinned        — --pin: the flake.lock rev snapshot (doc, rev)
#   live          — default: kailash-packages main HEAD
Source = namedtuple("Source", "doc rev kind")
LIVE_URL = (
    "https://github.com/kailash-os/kailash-packages/blob/main/manifest/categories.yaml"
)

LAYER_LABELS = {
    "CLASSIC": "CLASSIC",
    "ATTACK": "ATTACK",
    "DEFENCE": "DEFENCE",
    "OPS": "OPS",
}
LAYER_ORDER = ["CLASSIC", "ATTACK", "DEFENCE", "OPS"]

# required categories.yaml fields per row (the schema the generator relies on)
REQUIRED_FIELDS = ("id", "layer", "kind", "name", "tools")


class GenerateError(Exception):
    """Raised on an unreadable pin, missing file, or malformed census."""


def _load_yaml(text):
    """Parse YAML with PyYAML when importable, else the bounded stdlib fallback."""
    try:
        import yaml  # type: ignore[import-not-found]
    except ImportError:
        pass
    else:
        return yaml.safe_load(text)
    return _load_yaml_fallback(text)


def _load_yaml_fallback(text):
    """Minimal stdlib fallback for categories.yaml's shape.

    Handles exactly: header comments, `---`, `categories:` header, and a
    top-level list of flat dict rows (scalar string/int values only).
    Anything richer fails loudly — never silently mis-parses.
    """
    if "\t" in text:
        raise GenerateError("stdlib yaml fallback: tab indentation not supported")
    lines = [ln.rstrip() for ln in text.splitlines()]
    # find the `categories:` top-level key
    idx = None
    for i, ln in enumerate(lines):
        if ln.strip() == "categories:":
            idx = i
            break
    if idx is None:
        raise GenerateError("stdlib yaml fallback: no top-level 'categories:' key")
    rows = []
    current = None
    for ln in lines[idx + 1 :]:
        if ln.strip() in ("---", "") or ln.lstrip().startswith("#"):
            continue
        stripped = ln.lstrip()
        if stripped.startswith("- "):
            if current is not None:
                rows.append(current)
            current = {}
            body = stripped[2:]
            if _parse_kv(body, current) is None:
                raise GenerateError(
                    "stdlib yaml fallback: unparsable list entry: %r" % ln
                )
        elif current is not None and ln and ln[0].isspace():
            body = ln.strip()
            if _parse_kv(body, current) is None:
                if ":" not in body:
                    # prose continuation (multi-line comment text wrapped in
                    # the entry body) — not census data; skip silently
                    continue
                raise GenerateError("stdlib yaml fallback: unparsable line: %r" % ln)
        else:
            # a new top-level key: the categories list has ended
            break
    if current is not None:
        rows.append(current)
    return {"categories": rows}


def _parse_kv(body, into):
    """Parse `key: value` into a dict; values are scalars (str/int/none).

    Returns the parsed key, or None if the line is not a plain mapping.
    Multi-word unquoted strings pass through as strings; empty values
    become None (matching PyYAML's shape).
    """
    if ":" not in body:
        return None
    key, _, value = body.partition(":")
    key = key.strip()
    value = value.strip()
    if not key or not all(ch.isalnum() or ch in "-_" for ch in key):
        return None
    if value in ("", "~", "null"):
        into[key] = None
    elif value.startswith(("'", '"')) and value.endswith(value[0]) and len(value) >= 2:
        into[key] = value[1:-1]
    else:
        try:
            into[key] = int(value)
        except ValueError:
            into[key] = value
    return key


def packages_rev_from_flake_lock(lock_path):
    """Read the kailash-packages input node's locked rev from flake.lock."""
    with open(lock_path, encoding="utf-8") as fh:
        lock = json.load(fh)
    node = lock.get("nodes", {}).get(LOCK_INPUT)
    if not node:
        raise GenerateError("no %r input node in %s" % (LOCK_INPUT, lock_path))
    locked = node.get("locked") or {}
    if locked.get("type") != "github" or "rev" not in locked:
        raise GenerateError(
            "kailash-packages node is not a pinned github rev: %r" % (locked,)
        )
    return locked["rev"]


def _codeload_url(repo, rev):
    """Codeload tarball URL pinned to an exact rev (no floating heads)."""
    if not rev or not rev.strip():
        raise GenerateError("rev required (no floating heads)")
    return "https://codeload.github.com/%s/tar.gz/%s" % (repo, rev)


def _http_get(url):
    req = Request(url, headers={"User-Agent": "kailash-readme-table/1.0"})
    with urlopen(req, timeout=60) as resp:
        if resp.status != 200:
            raise GenerateError("GET %s -> HTTP %s" % (url, resp.status))
        return resp.read()


def categories_from_tarball(blob):
    """Extract categories.yaml from the pinned rev tarball; return (doc, rev_dir)."""
    tf = tarfile.open(fileobj=io.BytesIO(blob), mode="r:gz")
    target = os.path.join("manifest", "categories.yaml")
    for member in tf.getmembers():
        parts = member.name.split("/", 1)
        if len(parts) == 2 and parts[1] == target:
            fh = tf.extractfile(member)
            if fh is None:
                raise GenerateError("categories.yaml unreadable in the pinned tarball")
            return _load_yaml(fh.read().decode("utf-8"))
    raise GenerateError("manifest/categories.yaml not found in the pinned tarball")


def parse_categories(doc):
    """Census doc -> (rows, per-layer primary-slot totals, total).

    rows = category-kind rows only, in manifest order; data-packs excluded
    from rows AND totals (§3.6: data-packs are excluded from counts).
    A malformed row raises with its position named.
    """
    entries = None
    if isinstance(doc, dict):
        entries = doc.get("categories")
    if isinstance(entries, str):
        raise GenerateError(
            "categories.yaml parses to a string, not a mapping-with-list — "
            "the yaml.safe_load call consumed the doc (import the real "
            "pyyaml; not a stub)"
        )
    if not isinstance(entries, list) or not entries:
        raise GenerateError(
            "categories.yaml carries no top-level 'categories' list"
        )
    rows = []
    per_layer = {}
    for pos, e in enumerate(entries):
        if not isinstance(e, dict):
            raise GenerateError("entry at position %d is not a mapping" % pos)
        for field in REQUIRED_FIELDS:
            if field not in e or e[field] in (None, ""):
                raise GenerateError(
                    "entry %r missing required field: %s" % (e.get("id"), field)
                )
        if e["kind"] not in ("category", "data-pack"):
            raise GenerateError(
                "%s: bad kind %r (expected category | data-pack)"
                % (e["id"], e["kind"])
            )
        if e["layer"] not in LAYER_ORDER:
            raise GenerateError(
                "%s: bad layer %r (expected CLASSIC | ATTACK | DEFENCE | OPS)"
                % (e["id"], e["layer"])
            )
        if e["kind"] == "category":
            tools = e["tools"]
            if isinstance(tools, bool) or not isinstance(tools, int) or tools < 0:
                raise GenerateError(
                    "%s: tools must be a non-negative int" % e["id"]
                )
            rows.append({"id": e["id"], "layer": e["layer"], "name": e["name"],
                         "tools": tools})
            per_layer[e["layer"]] = per_layer.get(e["layer"], 0) + tools
    return rows, per_layer


def render_table(rows, per_layer, pin_rev=None):
    """Rows -> the README markdown table string (deterministic).

    `pin_rev` names the snapshot source ("flake.lock <sha>") in --pin
    mode; None (the default) renders the live-main source line.
    """
    pin_clause = "" if pin_rev is None else (
        " (snapshot: flake.lock pin %s)" % pin_rev)
    order = [l for l in LAYER_ORDER] + [l for l in sorted(per_layer)
                                        if l not in LAYER_ORDER]
    layers_present = [l for l in order if l in per_layer]
    total = sum(per_layer.values())
    lines = []
    lines.append(BEGIN_MARK)
    lines.append("")
    lines.append("| # | Category | Layer | Primary tool slots |")
    lines.append("| --- | --- | --- | --- |")
    for pos, r in enumerate(rows, 1):
        lines.append("| %d | %s | %s | %d |" % (pos, r["name"], r["layer"], r["tools"]))
    lines.append("| — | **Total** | %d categories | **%d** |" % (
        len(rows), total))
    lines.append("")
    breakdown = " · ".join(
        "%s %d" % (LAYER_LABELS.get(l, l), per_layer[l]) for l in layers_present
    )
    lines.append(
        "Per-layer primary tool slots: %s — %d categories, %d tool slots "
        "across the four layers (data-packs excluded from counts, "
        "[spec §2.6](https://github.com/kailash-os/kailash-os/blob/master/docs/spec.md"
        "#26-the-full-category-table-post-purge-census)), "
        "generated from [`categories.yaml`](%s) — the taxonomy's "
        "single home — on the `kailash-packages` main HEAD%s."
        % (breakdown, len(rows), total, LIVE_URL, pin_clause)
    )
    lines.append(END_MARK)
    return "\n".join(lines)


def categories_from_path(path):
    with open(path, encoding="utf-8") as fh:
        return _load_yaml(fh.read())


def live_categories_doc():
    """The LIVE taxonomy: categories.yaml at kailash-packages main HEAD."""
    return Source(
        doc=_load_yaml(_http_get(LIVE_RAW_URL).decode("utf-8")),
        rev=None,
        kind="live",
    )


def pin_categories_doc(lock_path=None):
    """Snapshot: categories.yaml at the flake.lock kailash-packages rev."""
    rev = packages_rev_from_flake_lock(
        lock_path or os.path.join(ROOT, "flake.lock")
    )
    blob = _http_get(_codeload_url(REPO, rev))
    return Source(
        doc=categories_from_tarball(blob),
        rev=rev,
        kind="pinned",
    )


# README seam: the generated block replaces exactly this span. Both markers
# are COMPLETE HTML comments — the render function emits them verbatim as
# the table's first and last lines, so counting and span-replacement work
# on well-formed comment boundaries.
BEGIN_MARK = ("<!-- BEGIN GENERATED CATEGORY TABLE "
              "(tools/generate-readme-table.py; KA-20.1) — do not edit -->")
END_MARK = "<!-- END GENERATED CATEGORY TABLE -->"


def readme_seam_failure(path):
    """None when README.md carries exactly one well-formed generated span."""
    if not os.path.exists(path):
        return "missing"
    text = open(path, encoding="utf-8").read()
    begins = text.count(BEGIN_MARK)
    ends = text.count(END_MARK)
    if begins == 0 or ends == 0:
        return "generated-table markers absent"
    if begins != 1 or ends != 1:
        return "marker count not one: BEGIN=%d END=%d" % (begins, ends)
    b = text.index(BEGIN_MARK)
    e = text.index(END_MARK)
    if e < b:
        return "END marker is before BEGIN marker"
    return None


def replace_span(text, new):
    """Replace the generated span (BEGIN..END, comments inclusive) with new.

    Both spans carry no trailing newline; the text after the span keeps
    whatever separated it from the END comment in the original file.
    """
    b = text.index(BEGIN_MARK)
    e = text.index(END_MARK)
    if e < b:
        raise GenerateError("END marker is before BEGIN marker")
    return text[:b] + new + text[e + len(END_MARK) :]


def resolve_source(check_fixture=None, manifest_path=None, pin=False,
                   lock_path=None):
    """Resolve the categories source; explicit overrides take precedence.

    check_fixture  — the inline RED/GREEN probe doc (never networked)
    manifest_path  — a local packages-repo categories.yaml
    pin            — the flake.lock snapshot (--pin)
    default        — the live taxonomy (kailash-packages main HEAD)
    """
    if check_fixture:
        return Source(doc=categories_from_path(check_fixture), rev=None,
                      kind="fixture")
    if manifest_path:
        return Source(doc=categories_from_path(manifest_path), rev=None,
                      kind="manifest-path")
    if pin:
        return pin_categories_doc(lock_path)
    return live_categories_doc()


def render_and_parse(source):
    """Source -> (rows, per_layer, table) with the pin clause wired."""
    rows, per_layer = parse_categories(source.doc)
    table = render_table(rows, per_layer, pin_rev=source.rev)
    return rows, per_layer, table


def check(readme_path, table=None, fixture_path=None, manifest_path=None,
          pin=False):
    """--check: compare the README's span against the generated table."""
    if table is None:
        _, _, table = render_and_parse(
            resolve_source(check_fixture=fixture_path,
                           manifest_path=manifest_path, pin=pin)
        )
    # the README span: BEGIN..END inclusive
    text = open(readme_path, encoding="utf-8").read()
    problem = readme_seam_failure(readme_path)
    if problem:
        print("readme-table: FAIL: the README table block fails the marker rule: %s" % problem)
        return 1
    b = text.index(BEGIN_MARK)
    e = text.index(END_MARK)
    span = text[b : e + len(END_MARK)]
    if span == table:
        print("readme-table: OK: the README table is identical to categories.yaml")
        return 0
    import difflib

    diff = difflib.unified_diff(
        span.splitlines(), table.splitlines(),
        fromfile="README.md (generated span)",
        tofile="categories.yaml (generated)",
        lineterm="",
    )
    print("readme-table: FAIL: the README category table shows drift against categories.yaml:")
    for line in list(diff)[:40]:
        print(line)
    return 1


def self_test() -> None:
    """Assert-based self-test: fixture fixtures for both modes + seam.

    The inline fixtures use the bounded stdlib-fallback grammar (flat
    scalars, one list key) so both the pyyaml and no-pyyaml parse paths
    read them identically.
    """
    fixture = "\n".join([
        "categories:",
        "  - id: c-a",
        "    layer: CLASSIC",
        "    kind: category",
        "    name: Cat A",
        "    tools: 3",
        "  - id: c-b",
        "    layer: ATTACK",
        "    kind: category",
        "    name: Cat B",
        "    tools: 2",
    ]) + "\n"
    doc = _load_yaml(fixture)
    rows, per_layer = parse_categories(doc)
    assert rows == [
        {"id": "c-a", "layer": "CLASSIC", "name": "Cat A", "tools": 3},
        {"id": "c-b", "layer": "ATTACK", "name": "Cat B", "tools": 2},
    ], rows
    assert per_layer == {"CLASSIC": 3, "ATTACK": 2}, per_layer
    t = render_table(rows, per_layer)
    assert "| # | Category | Layer | Primary tool slots |" in t
    assert "| 1 | Cat A | CLASSIC | 3 |" in t
    assert "| 2 | Cat B | ATTACK | 2 |" in t
    assert "| — | **Total** | 2 categories | **5** |" in t
    assert "CLASSIC 3 · ATTACK 2" in t
    # the fallback parser reads the same fixture
    fd = _load_yaml_fallback(fixture)
    rows_fb, per_layer_fb = parse_categories(fd)
    assert rows_fb == rows and per_layer_fb == per_layer
    # data-pack excluded from rows and totals
    doc2 = _load_yaml(fixture + (
        "  - id: c-data\n    layer: CLASSIC\n    kind: data-pack\n"
        "    name: Data Pack\n    tools: 6\n"
    ))
    rows2, per_layer2 = parse_categories(doc2)
    assert [r["id"] for r in rows2] == ["c-a", "c-b"]
    assert per_layer2 == {"CLASSIC": 3, "ATTACK": 2}
    # malformed rows raise with the id named
    for bad in ("    kind: foo", "    tools: -1", "    tools: true"):
        try:
            parse_categories(_load_yaml(fixture.replace("    kind: category", bad, 1)))
        except GenerateError as e:
            assert "c-a" in str(e), e
        else:
            raise AssertionError("malformed row must raise: %r" % bad)
    # README seam failure detection
    import tempfile

    with tempfile.TemporaryDirectory() as td:
        p = os.path.join(td, "README.md")
        open(p, "w").write("# Header\n\nNo table here yet.\n")
        assert readme_seam_failure(p) == "generated-table markers absent"
        open(p, "w").write(
            "# Header\n\n"
            + render_table(rows, per_layer)
            + "\n\n<!-- END GENERATED CATEGORY TABLE -->\n"
        )
        assert readme_seam_failure(p) == "marker count not one: BEGIN=1 END=2"
        # exact-span match
        good = "# Header\n\n" + render_table(rows, per_layer) + "\n\n# Tail\n"
        open(p, "w").write(good)
        assert readme_seam_failure(p) is None
        # drift check: span vs generated table
        b = open(p).read().index(BEGIN_MARK)
        e = open(p).read().index(END_MARK)
        span = open(p).read()[b : e + len(END_MARK)]
        assert span == render_table(rows, per_layer)
        # a drifted span fails the check (stdout suppressed: the FAIL
        # print is the negative case being exercised, not a failure of
        # the self-test)
        drifted = good.replace("| 1 | Cat A | CLASSIC | 3 |",
                               "| 1 | Cat A | CLASSIC | 4 |")
        open(p, "w").write(drifted)
        import contextlib as _ctxlib

        with _ctxlib.redirect_stdout(io.StringIO()):
            assert check(p, table=render_table(rows, per_layer)) == 1
        # an exact match passes (stdout suppressed: the OK print is the
        # positive case being exercised, not a self-test report)
        open(p, "w").write(good)
        with _ctxlib.redirect_stdout(io.StringIO()):
            assert check(p, table=render_table(rows, per_layer)) == 0
        # replace_span regenerates correctly
        regen = replace_span(good, render_table(rows, per_layer))
        assert regen == good
        # fixture-mode --check on a real file with the real span shape
        with _ctxlib.redirect_stdout(io.StringIO()):
            assert check(p, fixture_path=None, table=render_table(rows, per_layer)) == 0
    print("self-test OK")


def emit(source=None, manifest_path=None, pin=False, out=None):
    """Print the generated table for the resolved source mode."""
    if out is None:
        out = sys.stdout
    if source is None:
        source = resolve_source(manifest_path=manifest_path, pin=pin)
    _, _, table = render_and_parse(source)
    out.write(table + "\n")
    return 0


def main(argv):
    if "--self-test" in argv:
        self_test()
        return 0
    args = list(argv)
    manifest_path = None
    fixture_path = None
    pin = False
    for flag, sink in (("--manifest", "manifest"), ("--check-fixture", "fixture")):
        if flag in args:
            i = args.index(flag)
            try:
                value = args[i + 1]
            except IndexError:
                raise SystemExit("%s requires a path argument" % flag)
            args = args[:i] + args[i + 2 :]
            if sink == "manifest":
                manifest_path = value
            else:
                fixture_path = value
    if "--pin" in args:
        pin = True
        args.remove("--pin")
    if "--emit" in args:
        args.remove("--emit")
        return emit(manifest_path=manifest_path, pin=pin)
    targets = [a for a in args if not a.startswith("-")]
    readme = targets[0] if targets else os.path.join(ROOT, "README.md")
    return check(readme, fixture_path=fixture_path,
                 manifest_path=manifest_path, pin=pin)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
